window.PROBLEM_SOURCES["python-14"] = {"id": "python-14", "language": "python", "stub": {"path": "python/practice_problems/problem_14_contract_amendment.py", "source": "\"\"\"\n=============================================================================\nINTERVIEW PROBLEM 14: Contract Amendment Manager\nDifficulty: Senior Software Engineer | Estimated time: 45 min\n=============================================================================\n\nCONTEXT\n-------\nYou're building the amendment-tracking module for a contract platform.\nAfter a contract is signed, its terms can be modified through formal amendments.\nEach amendment specifies a set of field overrides that take effect from a given\ndate. To know the effective terms on any given date, you apply the base contract\nfields and then overlay amendments in chronological order up to that date.\n\nFor this problem you are building a ContractAmendmentManager class.\nStore all state in instance variables initialized in `__init__`.\nClass-level variables will bleed between tests and between\nContractAmendmentManager instances — avoid them.\nYou choose the internal data structures; the public interface is what matters.\n\nDATA MODEL\n----------\nContract (base):\n  {\n    \"contract_id\":  str,\n    \"title\":        str,\n    \"fields\":       dict,  # e.g. {\"value\": 50000, \"payment_terms\": \"net-30\"}\n  }\n\nAmendment:\n  {\n    \"amendment_id\":  str,\n    \"contract_id\":   str,\n    \"effective_on\":  str,   # ISO-8601 date string (\"YYYY-MM-DD\")\n    \"overrides\":     dict,  # field key → new value (may be a subset of fields)\n    \"note\":          str,   # human-readable reason for the amendment\n  }\n\nDates are ISO-8601 date strings (date-only).\nUse datetime.date.fromisoformat() for comparisons.\n\n# Example\n# mgr = ContractAmendmentManager()\n# mgr.add_contract(\"c-001\", \"Vendor MSA\", fields={\"value\": 50000, \"payment_terms\": \"net-30\"})\n#\n# mgr.add_amendment(\"amd-1\", \"c-001\", effective_on=\"2025-03-01\",\n#                   overrides={\"payment_terms\": \"net-45\"}, note=\"extended terms\")\n# mgr.add_amendment(\"amd-2\", \"c-001\", effective_on=\"2025-06-01\",\n#                   overrides={\"value\": 75000}, note=\"scope increase\")\n#\n# mgr.get_effective_contract(\"c-001\", as_of_date=\"2025-01-01\")\n# # -> {\"value\": 50000, \"payment_terms\": \"net-30\"}   (no amendments yet)\n#\n# mgr.get_effective_contract(\"c-001\", as_of_date=\"2025-04-15\")\n# # -> {\"value\": 50000, \"payment_terms\": \"net-45\"}   (amd-1 applied)\n#\n# mgr.get_effective_contract(\"c-001\", as_of_date=\"2025-07-01\")\n# # -> {\"value\": 75000, \"payment_terms\": \"net-45\"}   (amd-1 + amd-2 applied)\n\n=============================================================================\nPART 1 — Base contract management\n=============================================================================\n\nImplement `add_contract` and `get_base_contract`.\n\n\"\"\"\n\n\nclass ContractAmendmentManager:\n    \"\"\"\n    Tracks contract base terms and their amendments, and resolves the effective\n    contract state as of any given date.\n    \"\"\"\n\n    def __init__(self):\n        raise NotImplementedError\n\n    # ── Part 1 ────────────────────────────────────────────────────────────────\n\n    def add_contract(\n        self,\n        contract_id: str,\n        title: str,\n        fields: dict,\n    ) -> dict:\n        \"\"\"\n        Register a base contract.\n\n        Parameters\n        ----------\n        contract_id : str\n            Unique identifier.\n        title : str\n        fields : dict\n            Initial field values (e.g. {\"value\": 50000, \"payment_terms\": \"net-30\"}).\n            Store a copy — do not hold a reference to the caller's dict.\n\n        Returns\n        -------\n        dict\n            The stored contract dict.\n\n        Raises\n        ------\n        ValueError\n            If contract_id already exists.\n        \"\"\"\n        raise NotImplementedError\n\n    def get_base_contract(self, contract_id: str) -> dict:\n        \"\"\"\n        Return the base contract dict (original fields, no amendments applied).\n\n        Raises\n        ------\n        KeyError\n            If contract_id does not exist.\n        \"\"\"\n        raise NotImplementedError\n\n    # ── Part 2 ────────────────────────────────────────────────────────────────\n\n    def add_amendment(\n        self,\n        amendment_id: str,\n        contract_id: str,\n        effective_on: str,\n        overrides: dict,\n        note: str,\n    ) -> dict:\n        \"\"\"\n        Register an amendment for a contract.\n\n        Parameters\n        ----------\n        amendment_id : str\n            Unique amendment identifier.\n        contract_id : str\n        effective_on : str\n            ISO-8601 date string from which this amendment takes effect.\n        overrides : dict\n            Partial field updates. Keys may be a subset of the base contract\n            fields, or introduce new fields.\n            Store a copy — do not hold a reference to the caller's dict.\n        note : str\n            Human-readable reason.\n\n        Returns\n        -------\n        dict\n            The stored amendment dict.\n\n        Raises\n        ------\n        ValueError\n            If amendment_id already exists.\n        KeyError\n            If contract_id does not exist.\n        \"\"\"\n        raise NotImplementedError\n\n    def get_amendments(self, contract_id: str) -> list[dict]:\n        \"\"\"\n        Return all amendments for a contract, sorted by effective_on ascending,\n        then amendment_id ascending (for deterministic ordering when dates match).\n\n        Parameters\n        ----------\n        contract_id : str\n\n        Returns\n        -------\n        list[dict]\n            List of amendment dicts.\n\n        Raises\n        ------\n        KeyError\n            If contract_id does not exist.\n        \"\"\"\n        raise NotImplementedError\n\n    def get_effective_contract(self, contract_id: str, as_of_date: str) -> dict:\n        \"\"\"\n        Return the resolved field values for a contract as of as_of_date.\n\n        Start with the base fields from `get_base_contract`, then apply\n        amendments in chronological order (earliest first) where\n        effective_on <= as_of_date, overlaying their overrides.\n\n        Uses get_base_contract and get_amendments internally — do not\n        duplicate their logic.\n\n        Parameters\n        ----------\n        contract_id : str\n        as_of_date : str\n            ISO-8601 date string.\n\n        Returns\n        -------\n        dict\n            Resolved {field: value} mapping at as_of_date.\n\n        Raises\n        ------\n        KeyError\n            If contract_id does not exist.\n        \"\"\"\n        raise NotImplementedError\n\n    # ── Part 3 ────────────────────────────────────────────────────────────────\n\n    def get_value_history(self, contract_id: str, field: str) -> list[dict]:\n        \"\"\"\n        Return the full history of a specific field's value across base and\n        all amendments that touched it, in chronological order.\n\n        Parameters\n        ----------\n        contract_id : str\n        field : str\n            The field name to trace.\n\n        Returns\n        -------\n        list[dict]\n            Each item:\n            {\n              \"effective_on\":   str,          # ISO-8601 date; \"base\" for the original value\n              \"value\":          any,\n              \"source\":         str,          # \"base\" | amendment_id\n            }\n            Sorted by effective_on ascending (base always first).\n\n        Raises\n        ------\n        KeyError\n            If contract_id does not exist, or if the field is not present in\n            the base contract or any amendment for that contract.\n        \"\"\"\n        raise NotImplementedError\n\n    def get_amendment_summary(self, contract_id: str) -> dict:\n        \"\"\"\n        Return a summary of amendment activity for a contract.\n        Uses get_amendments and get_effective_contract internally — do not\n        duplicate their logic.\n\n        Parameters\n        ----------\n        contract_id : str\n\n        Returns\n        -------\n        dict\n            {\n              \"contract_id\":       str,\n              \"amendment_count\":   int,\n              \"fields_amended\":    list[str],   # unique field names ever overridden,\n                                                # sorted ascending\n              \"latest_amendment\":  str | None,  # ISO-8601 date of most recent\n                                                # amendment, or None if no amendments\n              \"current_fields\":    dict,        # result of get_effective_contract\n                                                # called with today's date\n            }\n            For \"today\" use the most recent amendment's effective_on date if\n            any amendments exist, otherwise use \"2099-12-31\" as a far-future\n            sentinel so all amendments are included.\n\n        Raises\n        ------\n        KeyError\n            If contract_id does not exist.\n        \"\"\"\n        raise NotImplementedError\n"}, "test": {"path": "python/tests/test_problem_14_contract_amendment.py", "source": "\"\"\"Tests for Problem 14: Contract Amendment Manager\n\nRun from the python/ directory:\n    pytest tests/test_problem_14_contract_amendment.py -v\n\"\"\"\n\nimport pytest\nfrom practice_problems.problem_14_contract_amendment import ContractAmendmentManager\n\n# ---------------------------------------------------------------------------\n# Shared dates\n# ---------------------------------------------------------------------------\nD_BASE  = \"2025-01-01\"   # base / before any amendments\nD_AMD1  = \"2025-03-01\"   # amendment 1 effective date\nD_AMD2  = \"2025-06-01\"   # amendment 2 effective date\nD_AMD3  = \"2025-09-01\"   # amendment 3 effective date\nD_AFTER = \"2025-12-31\"   # well after all amendments\n\n\n# ---------------------------------------------------------------------------\n# Fixtures\n# ---------------------------------------------------------------------------\n\n@pytest.fixture\ndef fresh_mgr():\n    \"\"\"Empty ContractAmendmentManager.\"\"\"\n    return ContractAmendmentManager()\n\n\n@pytest.fixture\ndef mgr():\n    \"\"\"\n    Pre-seeded manager:\n      c-seed-1  \"Vendor MSA\"\n                fields = {\"value\": 50000, \"payment_terms\": \"net-30\", \"currency\": \"USD\"}\n                amd-s1 (2025-03-01): overrides = {\"payment_terms\": \"net-45\"}\n                amd-s2 (2025-06-01): overrides = {\"value\": 75000}\n\n      c-seed-2  \"NDA Agreement\"\n                fields = {\"term_years\": 2, \"auto_renew\": True}\n                (no amendments)\n    \"\"\"\n    m = ContractAmendmentManager()\n    m.add_contract(\n        \"c-seed-1\", \"Vendor MSA\",\n        fields={\"value\": 50000, \"payment_terms\": \"net-30\", \"currency\": \"USD\"},\n    )\n    m.add_contract(\n        \"c-seed-2\", \"NDA Agreement\",\n        fields={\"term_years\": 2, \"auto_renew\": True},\n    )\n    m.add_amendment(\n        \"amd-s1\", \"c-seed-1\",\n        effective_on=D_AMD1,\n        overrides={\"payment_terms\": \"net-45\"},\n        note=\"extended payment terms\",\n    )\n    m.add_amendment(\n        \"amd-s2\", \"c-seed-1\",\n        effective_on=D_AMD2,\n        overrides={\"value\": 75000},\n        note=\"scope increase\",\n    )\n    return m\n\n\n# ---------------------------------------------------------------------------\n# PART 1 — Base contract management\n# ---------------------------------------------------------------------------\n\nclass TestAddContract:\n    def test_returns_contract_dict(self, fresh_mgr):\n        c = fresh_mgr.add_contract(\"c-add-1\", \"Test\", fields={\"x\": 1})\n        assert c[\"contract_id\"] == \"c-add-1\"\n        assert c[\"title\"] == \"Test\"\n        assert c[\"fields\"][\"x\"] == 1\n\n    def test_stores_copy_of_fields(self, fresh_mgr):\n        original = {\"x\": 1}\n        fresh_mgr.add_contract(\"c-copy-1\", \"Test\", fields=original)\n        original[\"x\"] = 999\n        assert fresh_mgr.get_base_contract(\"c-copy-1\")[\"fields\"][\"x\"] == 1\n\n    def test_duplicate_raises(self, fresh_mgr):\n        fresh_mgr.add_contract(\"c-dup-am\", \"A\", fields={})\n        with pytest.raises(ValueError):\n            fresh_mgr.add_contract(\"c-dup-am\", \"B\", fields={})\n\n\nclass TestGetBaseContract:\n    def test_returns_original_fields(self, mgr):\n        base = mgr.get_base_contract(\"c-seed-1\")\n        # Even though amendments exist, base fields are unchanged\n        assert base[\"fields\"][\"payment_terms\"] == \"net-30\"\n        assert base[\"fields\"][\"value\"] == 50000\n\n    def test_unknown_raises(self, mgr):\n        with pytest.raises(KeyError):\n            mgr.get_base_contract(\"no-such\")\n\n\n# ---------------------------------------------------------------------------\n# PART 2 — Amendments and effective contract\n# ---------------------------------------------------------------------------\n\nclass TestAddAmendment:\n    def test_returns_amendment_dict(self, mgr):\n        amd = mgr.add_amendment(\n            \"amd-add-1\", \"c-seed-1\",\n            effective_on=D_AMD3,\n            overrides={\"currency\": \"EUR\"},\n            note=\"switch currency\",\n        )\n        assert amd[\"amendment_id\"] == \"amd-add-1\"\n        assert amd[\"contract_id\"]  == \"c-seed-1\"\n        assert amd[\"effective_on\"] == D_AMD3\n        assert amd[\"overrides\"] == {\"currency\": \"EUR\"}\n        assert amd[\"note\"] == \"switch currency\"\n\n    def test_stores_copy_of_overrides(self, fresh_mgr):\n        fresh_mgr.add_contract(\"c-amd-copy\", \"T\", fields={\"x\": 1})\n        overrides = {\"x\": 2}\n        fresh_mgr.add_amendment(\"amd-copy-1\", \"c-amd-copy\", effective_on=D_AMD1, overrides=overrides, note=\"\")\n        overrides[\"x\"] = 999\n        amendments = fresh_mgr.get_amendments(\"c-amd-copy\")\n        assert amendments[0][\"overrides\"][\"x\"] == 2\n\n    def test_duplicate_amendment_raises(self, mgr):\n        with pytest.raises(ValueError):\n            mgr.add_amendment(\"amd-s1\", \"c-seed-1\", effective_on=D_AMD3, overrides={}, note=\"\")\n\n    def test_unknown_contract_raises(self, mgr):\n        with pytest.raises(KeyError):\n            mgr.add_amendment(\"amd-new\", \"no-such\", effective_on=D_AMD1, overrides={}, note=\"\")\n\n\nclass TestGetAmendments:\n    def test_sorted_by_effective_on(self, mgr):\n        amendments = mgr.get_amendments(\"c-seed-1\")\n        dates = [a[\"effective_on\"] for a in amendments]\n        assert dates == sorted(dates)\n\n    def test_empty_when_none(self, mgr):\n        assert mgr.get_amendments(\"c-seed-2\") == []\n\n    def test_unknown_raises(self, mgr):\n        with pytest.raises(KeyError):\n            mgr.get_amendments(\"no-such\")\n\n    def test_same_date_ordered_by_amendment_id(self, fresh_mgr):\n        fresh_mgr.add_contract(\"c-same-dt\", \"T\", fields={\"x\": 0})\n        fresh_mgr.add_amendment(\"amd-z\", \"c-same-dt\", effective_on=D_AMD1, overrides={\"x\": 2}, note=\"\")\n        fresh_mgr.add_amendment(\"amd-a\", \"c-same-dt\", effective_on=D_AMD1, overrides={\"x\": 1}, note=\"\")\n        amendments = fresh_mgr.get_amendments(\"c-same-dt\")\n        ids = [a[\"amendment_id\"] for a in amendments]\n        assert ids == sorted(ids)\n\n\nclass TestGetEffectiveContract:\n    def test_before_any_amendments(self, mgr):\n        fields = mgr.get_effective_contract(\"c-seed-1\", as_of_date=D_BASE)\n        assert fields[\"payment_terms\"] == \"net-30\"\n        assert fields[\"value\"] == 50000\n\n    def test_after_first_amendment(self, mgr):\n        fields = mgr.get_effective_contract(\"c-seed-1\", as_of_date=\"2025-04-15\")\n        assert fields[\"payment_terms\"] == \"net-45\"\n        assert fields[\"value\"] == 50000   # amd-s2 not yet effective\n\n    def test_after_all_amendments(self, mgr):\n        fields = mgr.get_effective_contract(\"c-seed-1\", as_of_date=D_AFTER)\n        assert fields[\"payment_terms\"] == \"net-45\"\n        assert fields[\"value\"] == 75000\n\n    def test_original_unamended_fields_preserved(self, mgr):\n        fields = mgr.get_effective_contract(\"c-seed-1\", as_of_date=D_AFTER)\n        assert fields[\"currency\"] == \"USD\"\n\n    def test_no_amendments_returns_base(self, mgr):\n        fields = mgr.get_effective_contract(\"c-seed-2\", as_of_date=D_AFTER)\n        assert fields[\"term_years\"] == 2\n        assert fields[\"auto_renew\"] is True\n\n    def test_exact_effective_date_is_inclusive(self, mgr):\n        # amd-s1 effective_on = D_AMD1; querying exactly D_AMD1 should apply it\n        fields = mgr.get_effective_contract(\"c-seed-1\", as_of_date=D_AMD1)\n        assert fields[\"payment_terms\"] == \"net-45\"\n\n    def test_does_not_mutate_base(self, mgr):\n        mgr.get_effective_contract(\"c-seed-1\", as_of_date=D_AFTER)\n        base = mgr.get_base_contract(\"c-seed-1\")\n        assert base[\"fields\"][\"payment_terms\"] == \"net-30\"\n\n    def test_unknown_raises(self, mgr):\n        with pytest.raises(KeyError):\n            mgr.get_effective_contract(\"no-such\", as_of_date=D_AFTER)\n\n\n# ---------------------------------------------------------------------------\n# PART 3 — Value history and amendment summary\n# ---------------------------------------------------------------------------\n\nclass TestGetValueHistory:\n    def test_base_value_included_first(self, mgr):\n        history = mgr.get_value_history(\"c-seed-1\", \"value\")\n        assert history[0][\"source\"] == \"base\"\n        assert history[0][\"value\"] == 50000\n\n    def test_amendment_override_included(self, mgr):\n        history = mgr.get_value_history(\"c-seed-1\", \"payment_terms\")\n        sources = [e[\"source\"] for e in history]\n        assert \"amd-s1\" in sources\n\n    def test_only_amendments_that_touched_field(self, mgr):\n        # amd-s2 changes \"value\", not \"payment_terms\"\n        history = mgr.get_value_history(\"c-seed-1\", \"payment_terms\")\n        sources = [e[\"source\"] for e in history]\n        assert \"amd-s2\" not in sources\n\n    def test_sorted_chronologically(self, mgr):\n        history = mgr.get_value_history(\"c-seed-1\", \"value\")\n        # base first, then amendment entries in date order\n        assert history[0][\"source\"] == \"base\"\n        dates = [e[\"effective_on\"] for e in history if e[\"source\"] != \"base\"]\n        assert dates == sorted(dates)\n\n    def test_field_not_present_raises(self, mgr):\n        with pytest.raises(KeyError):\n            mgr.get_value_history(\"c-seed-1\", \"nonexistent_field\")\n\n    def test_unknown_contract_raises(self, mgr):\n        with pytest.raises(KeyError):\n            mgr.get_value_history(\"no-such\", \"value\")\n\n\nclass TestGetAmendmentSummary:\n    def test_amendment_count(self, mgr):\n        summary = mgr.get_amendment_summary(\"c-seed-1\")\n        assert summary[\"amendment_count\"] == 2\n\n    def test_fields_amended_sorted(self, mgr):\n        summary = mgr.get_amendment_summary(\"c-seed-1\")\n        assert summary[\"fields_amended\"] == sorted([\"payment_terms\", \"value\"])\n\n    def test_latest_amendment_date(self, mgr):\n        summary = mgr.get_amendment_summary(\"c-seed-1\")\n        assert summary[\"latest_amendment\"] == D_AMD2\n\n    def test_current_fields_reflect_all_amendments(self, mgr):\n        summary = mgr.get_amendment_summary(\"c-seed-1\")\n        assert summary[\"current_fields\"][\"payment_terms\"] == \"net-45\"\n        assert summary[\"current_fields\"][\"value\"] == 75000\n\n    def test_no_amendments_returns_none_latest(self, mgr):\n        summary = mgr.get_amendment_summary(\"c-seed-2\")\n        assert summary[\"latest_amendment\"] is None\n        assert summary[\"amendment_count\"] == 0\n        assert summary[\"fields_amended\"] == []\n\n    def test_unknown_raises(self, mgr):\n        with pytest.raises(KeyError):\n            mgr.get_amendment_summary(\"no-such\")\n"}, "parts": [{"part": 1, "source": "PART 1 — Base contract management\n"}], "implementationSurface": null};
